import numpy as np

def sim(vw=4.1, vr=8.4,g=1.75,r=7.2,ef=.52,eo=.55,damp=.992):
 p=np.array([[132.1,8.5],[122.7,20.8]],float);v=np.array([[0,vw],[0,vr]],float)
 out=[]
 for fr in range(96):
  out.append(p.copy())
