     v[0]+=j*n;v[1]-=j*n
   v*=damp**dt
  # sleeping-ish ground damping
  for i in range(2):
   if p[i,1]>94-r-.05 and abs(v[i,1])<1: v[i,1]=0
 return np.array(out)
